export const WINDOW_LOCALES = Object.freeze(Object.keys(STRINGS));
export const windowStringKeys = (locale) => Object.keys(STRINGS[locale] ?? {});
// The tag for <html lang>, Intl and the spell checker.
export const languageTag = (locale) => ({ zh: "zh-Hans", "zh-Hant": "zh-Hant", pt: "pt-BR" }[locale] ?? locale);

// When a wait ends: "11:10", or "Sat 11:10" when that is not today. A time that is always near, such
// as the end of a stream, leaves the day out.
export function timeOfDay(at, locale, { day = true } = {}) {
  const when = new Date(at);
  const today = !day || when.toDateString() === new Date().toDateString();
  try {
    return new Intl.DateTimeFormat(languageTag(locale), { ...(today ? {} : { weekday: "short" }), hour: "numeric", minute: "2-digit" }).format(when);
  } catch { return when.toTimeString().slice(0, 5); }
}

export function windowStrings(locale) {
  const own = STRINGS[locale] ?? {};
  // Traditional Chinese has every string; any other gap reads English.
  return (key, params = {}) => String(own[key] ?? STRINGS.en[key] ?? key).replace(/\{(\w+)\}/gu, (match, name) => params[name] ?? match);
}

/** The window's language from the system's preferred list, such as ["zh-Hant-TW", "en-US"]. */
export function windowLocale(preferred = []) {
  for (const tag of preferred) {
    const [language, ...rest] = String(tag).toLowerCase().split(/[-_]/u);
    if (language === "zh") return !rest.includes("hans") && rest.some((part) => ["hant", "tw", "hk", "mo"].includes(part)) ? "zh-Hant" : "zh";
    if (STRINGS[language]) return language;
  }
  return "en";
}
